import { Method, type MatrixHttpApi, type IHttpOpts } from "../../http-api/index.ts";
import type { IKeyValueStore } from "../../store/KeyValueStore.ts";
import type { IRoomEvent, IStateEvent } from "../../sync-accumulator.ts";
import type { IContent } from "../../models/event.ts";
import type { EmptyObject } from "../../@types/common.ts";
import { logger } from "../../logger.ts";

export interface RoomManagerEvents {
    roomCreated: { roomId: string };
    roomJoined: { roomId: string };
    roomLeft: { roomId: string };
    roomInvited: { roomId: string };
    error: Error;
}

export interface CreateRoomOptions {
    room_alias_name?: string;
    name?: string;
    topic?: string;
    invite?: string[];
    invite_3pid?: Array<{ id_server: string; medium: string; address: string }>;
    visibility?: "public" | "private";
    preset?: "private_chat" | "public_chat" | "trusted_private_chat" | "custom";
    room_version?: string;
    creation_content?: IContent;
    initial_state?: IStateEvent[];
    power_level_content_override?: IContent;
}

export interface RoomStateResponse {
    events: IStateEvent[];
}

export interface RoomMembersResponse {
    chunk: IRoomEvent[];
}

export interface PublicRoomsResponse {
    chunk: Array<{
        room_id: string;
        name?: string;
        topic?: string;
        num_joined_members: number;
        world_readable?: boolean;
        guest_can_join?: boolean;
        avatar_url?: string;
    }>;
    next_batch: string;
    prev_batch: string;
    total_room_count_estimate: number;
}

export interface RoomDirectoryVisibilityResponse {
    visibility: "public" | "private";
}

export class RoomManager {
    private rooms: Map<string, RoomData> = new Map();

    public constructor(
        private http: MatrixHttpApi<IHttpOpts>,
        private store: IKeyValueStore,
    ) {
        this.loadRooms();
    }

    public async createRoom(options: CreateRoomOptions = {}): Promise<{ room_id: string }> {
        const response = await this.http.authedRequest<{ room_id: string }>(
            Method.Post,
            "/createRoom",
            undefined,
            options,
        );

        const roomId = response.room_id;
        this.rooms.set(roomId, {
            roomId,
            joined: true,
            membership: "join",
            createdAt: Date.now(),
        });

        await this.saveRooms();
        return response;
    }

    public async joinRoom(roomIdOrAlias: string, viaServers?: string[]): Promise<{ room_id: string }> {
        const body: Record<string, unknown> = {};
        if (viaServers && viaServers.length > 0) {
            body.via = viaServers;
        }

        const response = await this.http.authedRequest<{ room_id: string }>(
            Method.Post,
            `/join/${encodeURIComponent(roomIdOrAlias)}`,
            undefined,
            body,
        );

        const roomId = response.room_id;
        this.rooms.set(roomId, {
            roomId,
            joined: true,
            membership: "join",
            joinedAt: Date.now(),
        });

        await this.saveRooms();
        return response;
    }

    public async joinRoomById(roomId: string, viaServers?: string[]): Promise<{ room_id: string }> {
        const body: Record<string, unknown> = {};
        if (viaServers && viaServers.length > 0) {
            body.via = viaServers;
        }

        const response = await this.http.authedRequest<{ room_id: string }>(
            Method.Post,
            `/rooms/${encodeURIComponent(roomId)}/join`,
            undefined,
            body,
        );

        this.rooms.set(roomId, {
            roomId,
            joined: true,
            membership: "join",
            joinedAt: Date.now(),
        });

        await this.saveRooms();
        return response;
    }

    public async leave(roomId: string): Promise<void> {
        await this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/leave`);

        const room = this.rooms.get(roomId);
        if (room) {
            room.joined = false;
            room.membership = "leave";
            room.leftAt = Date.now();
        }

        await this.saveRooms();
    }

    public async forget(roomId: string): Promise<void> {
        await this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/forget`);

        this.rooms.delete(roomId);
        await this.saveRooms();
    }

    public async invite(roomId: string, userId: string): Promise<void> {
        await this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/invite`, undefined, {
            user_id: userId,
        });
    }

    public async inviteByEmail(roomId: string, email: string): Promise<void> {
        await this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/invite`, undefined, {
            "m.id.server": email,
        });
    }

    public async kick(roomId: string, userId: string, reason?: string): Promise<EmptyObject> {
        const body: Record<string, unknown> = {
            user_id: userId,
        };
        if (reason) {
            body.reason = reason;
        }

        return this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/kick`, undefined, body);
    }

    public async ban(roomId: string, userId: string, reason?: string): Promise<EmptyObject> {
        const body: Record<string, unknown> = {
            user_id: userId,
        };
        if (reason) {
            body.reason = reason;
        }

        return this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/ban`, undefined, body);
    }

    public async unban(roomId: string, userId: string): Promise<EmptyObject> {
        return this.http.authedRequest(Method.Post, `/rooms/${encodeURIComponent(roomId)}/unban`, undefined, {
            user_id: userId,
        });
    }

    public async getRoomState(roomId: string, eventType?: string, stateKey?: string): Promise<RoomStateResponse> {
        let path = `/rooms/${encodeURIComponent(roomId)}/state`;
        if (eventType) {
            path += `/${encodeURIComponent(eventType)}`;
            if (stateKey) {
                path += `/${encodeURIComponent(stateKey)}`;
            }
        }

        return this.http.authedRequest(Method.Get, path);
    }

    public async setRoomState(
        roomId: string,
        eventType: string,
        content: IContent,
        stateKey?: string,
    ): Promise<{ event_id: string }> {
        let path = `/rooms/${encodeURIComponent(roomId)}/state/${encodeURIComponent(eventType)}`;
        if (stateKey) {
            path += `/${encodeURIComponent(stateKey)}`;
        }

        return this.http.authedRequest(Method.Put, path, undefined, content);
    }

    public async getRoomMembers(roomId: string): Promise<RoomMembersResponse> {
        return this.http.authedRequest(Method.Get, `/rooms/${encodeURIComponent(roomId)}/members`);
    }

    public async getJoinedMembers(roomId: string): Promise<{ joined: Record<string, Record<string, unknown>> }> {
        return this.http.authedRequest(Method.Get, `/rooms/${encodeURIComponent(roomId)}/joined_members`);
    }

    public async getRoomDirectoryVisibility(roomId: string): Promise<RoomDirectoryVisibilityResponse> {
        return this.http.authedRequest(Method.Get, `/directory/room/${encodeURIComponent(roomId)}`);
    }

    public async setRoomDirectoryVisibility(roomId: string, visibility: "public" | "private"): Promise<EmptyObject> {
        return this.http.authedRequest(Method.Put, `/directory/list/room/${encodeURIComponent(roomId)}`, undefined, {
            visibility,
        });
    }

    public async getPublicRooms(options?: {
        limit?: number;
        since?: string;
        server?: string;
        filter?: {
            generic_search_term?: string;
            room_types?: string[];
        };
    }): Promise<PublicRoomsResponse> {
        return this.http.authedRequest(Method.Post, "/publicRooms", undefined, options);
    }

    public async reportEvent(roomId: string, eventId: string, score: number, reason: string): Promise<EmptyObject> {
        return this.http.authedRequest(
            Method.Post,
            `/rooms/${encodeURIComponent(roomId)}/report/${encodeURIComponent(eventId)}`,
            undefined,
            {
                score,
                reason,
            },
        );
    }

    public getRoom(roomId: string): RoomData | undefined {
        return this.rooms.get(roomId);
    }

    public getRooms(): RoomData[] {
        return Array.from(this.rooms.values());
    }

    public getJoinedRooms(): RoomData[] {
        return Array.from(this.rooms.values()).filter((room) => room.joined);
    }

    public isJoined(roomId: string): boolean {
        const room = this.rooms.get(roomId);
        return room?.joined ?? false;
    }

    public updateRoomData(roomId: string, data: Partial<RoomData>): void {
        const room = this.rooms.get(roomId);
        if (room) {
            Object.assign(room, data);
            this.saveRooms();
        }
    }

    private async saveRooms(): Promise<void> {
        const rooms = Array.from(this.rooms.entries());
        await this.store.setItem("rooms", rooms);
    }

    private async loadRooms(): Promise<void> {
        try {
            const rooms = await this.store.getItem<Array<[string, RoomData]>>("rooms");
            if (rooms) {
                this.rooms = new Map(rooms);
            }
        } catch (error) {
            logger.warn("Failed to load rooms:", error);
        }
    }
}

export interface RoomData {
    roomId: string;
    joined: boolean;
    membership: "join" | "leave" | "ban" | "invite";
    name?: string;
    topic?: string;
    avatar?: string;
    createdAt?: number;
    joinedAt?: number;
    leftAt?: number;
    lastEvent?: IRoomEvent;
}
